package com.wandertrace.config;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.*;import org.springframework.web.cors.*;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)).authorizeHttpRequests(a->a.requestMatchers("/api/public/**","/api/auth/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().permitAll()).build();}@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean CorsConfigurationSource cors(@Value("${wandertrace.cors.allowed-origins}")String origins){var c=new CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE"));c.setAllowedHeaders(List.of("Content-Type","X-Requested-With"));c.setAllowCredentials(true);var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
